# summary ≤ 60 words; population: a string such as "about 800,000"; feel: one sentence of atmosphere (≤ 25 words).
PERIODS = [
    dict(id="kingdom-600bce", label="Regal Rome", year=-600, startYear=-753, endYear=-509,
         summary="Hill villages fusing into a town under Etruscan-style kings. The Forum marsh is being drained by the Cloaca, huts of wattle and thatch give way to houses on tufa footings with terracotta roofs, and the Capitoline temple is rising. Timber, thatch, tufa and clay; a wooden bridge; salt and bronze traded at the river ford.",
         population="perhaps 25,000",
         feel="Smoke from thatched roofs, the smell of the marsh, a bronze-smith's hammer ringing under the Palatine."),
    dict(id="republic-200bce", label="Middle Republic", year=-200, startYear=-508, endYear=-134,
         summary="Rome just after Hannibal: a crowded, muddy city of tufa, timber and terracotta ruled by the Senate and annual magistrates. Stone temples, the first basilicas and porticoes in the Forum, the Emporium and stone quays on the river, two aqueducts, streets only now being paved. Greek loot, Greek plays and Greek ideas begin to arrive.",
         population="perhaps 200,000",
         feel="Grain barges on the river, Plautus in a wooden theatre, the Forum packed with litigants, bankers and soldiers home from Greece."),
    dict(id="republic-50bce", label="Late Republic", year=-50, startYear=-133, endYear=-27,
         summary="Capital of the Mediterranean, bursting its old walls: citizens, freedmen and slaves packed into tenements, the first marble temples, Pompey's stone theatre in the Campus Martius, Caesar's new Forum under construction. Politics is fought in the streets by gangs; aqueducts, the river port and the free grain dole keep the city alive.",
         population="perhaps 750,000",
         feel="Election mobs, street gangs, Cicero's voice from the Rostra; carts banned by day, the Subura burning somewhere every week."),
    dict(id="empire-100ce", label="High Empire", year=100, startYear=-26, endYear=192,
         summary="Trajan's Rome at its peak: marble over brick-faced concrete, fourteen regions, the Colosseum, the imperial fora, great baths, nine aqueducts and tenements six storeys high. The emperor rules from the Palatine; the Senate meets and obeys. Free grain, games and water for a million people fed by sea from Egypt and Africa.",
         population="about 1,000,000",
         feel="Marble glare at noon, forty thousand tenements, the roar of the amphitheatre and the clatter of carts all night."),
    dict(id="empire-215ce", label="Severan Rome", year=215, startYear=193, endYear=284,
         summary="The Severan city: Caracalla's enormous baths, the Septizodium, a marble plan of every street displayed in the Temple of Peace. Still a million people on the dole, now with free oil too; soldier-emperors from Africa and Syria, gilded brick and coloured marble. The Aurelian Walls (271–275) will soon enclose a city that has begun to fear the north.",
         population="perhaps 1,000,000",
         feel="Soldiers everywhere, the biggest baths yet, the brick city at its most crowded and most confident."),
    dict(id="late-400ce", label="Late Antiquity", year=400, startYear=285, endYear=476,
         summary="A Christian capital without an emperor, inside the Aurelian Walls: basilicas at the Lateran, St Peter's and across the city; temples closed since 391 and stripped of bronze. Senators still rich, the population shrinking; Alaric's Goths sack the city in 410. Old marble reused, tenements decaying, the dole continuing, the games fading away.",
         population="perhaps 600,000",
         feel="Chant from new basilicas, bronze torn from old roofs, a thinning crowd in a city built for a million."),
    dict(id="medieval-1300", label="Medieval Rome", year=1300, startYear=477, endYear=1420,
         summary="A town huddled in the Tiber bend and Trastevere inside walls built for a million: tower-houses of the Orsini and Colonna, brick churches with bell-towers, ancient marble burned for lime, two-thirds of the walled area vineyards and ruins. Ruled contentiously by pope, barons and commune; Boniface VIII's Jubilee of 1300 floods the streets with pilgrims.",
         population="perhaps 30,000",
         feel="Pilgrims, cows in the Forum, baronial towers, and the marvels of the Mirabilia half-buried among the vines."),
    dict(id="renaissance-1560", label="Renaissance Rome", year=1560, startYear=1421, endYear=1600,
         summary="The papal capital rebuilt: straight new streets (Via Giulia, Coronari), palaces of travertine and stucco, St Peter's dome rising, aqueducts being repaired, Michelangelo's Capitol under way. Recovering from the Sack of 1527 under Pius IV, with the Inquisition, the Index, the Ghetto (1555) and the Council of Trent: a city of clerics, bankers, courtesans and pilgrims.",
         population="about 80,000",
         feel="Carriages and cardinals on new streets, printers, lime-kilns and Pasquino's wit beneath the unfinished dome."),
]

